mapper.select:
SELECT cp.id, cp.factory_id, cp.order_id, o.order_no, o.style_id, s.style_code, s.style_name, cp.color, cp.size, cp.bed_no, cp.plan_qty, cp.actual_qty, cp.qty_per_bundle, cp.bundle_count, cp.cutting_date, cp.barcode, cp.status, cp.created_at FROM cutting_plan cp LEFT JOIN `order` o ON cp.order_id = o.id AND o.deleted = 0 LEFT JOIN style s ON o.style_id = s.id AND s.deleted = 0 WHERE cp.factory_id = #{factoryId} AND cp.deleted = 0
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND s.style_code LIKE CONCAT('%', #{styleCode}, '%')
AND cp.color = #{color}
AND cp.size = #{size}
ORDER BY cp.created_at DESC
